const MAX_COMPUTE_STDERR = 64_000
function addComputeEvent(jobId: string, type: ComputeJobEvent['type'], message: string, progress?: number): void {
  const event: ComputeJobEvent = { id: `event-${createRunId()}`, jobId, type, message, progress, createdAt: new Date().toISOString() }
  computeEvents.set(jobId, [...(computeEvents.get(jobId) ?? []), event])
}
// workflow 是能力模块（modules/workflow/），计算依赖生物模块的公共层与原生库。
// 打包后两者一起放到 resources/modules/ 下，路径结构与开发态保持一致。
function computeResourceRoot(): string { return isDevelopment ? resolve(currentDir, '..', '..', 'modules') : join(process.resourcesPath, 'modules') }
// 打包后复用随客户端发布的嵌入式 Python（与内置 RAG 同一份运行时），不再单独打包一份解释器；
// workflow 只用标准库与 ctypes，不需要额外的第三方包。
function computePythonExecutable(): string { if (isDevelopment) return process.env.IDEA_PYTHON_EXECUTABLE || 'python'; return process.platform === 'win32' ? join(process.resourcesPath, 'rag', 'runtime', 'python', 'python.exe') : join(process.resourcesPath, 'rag', 'runtime', 'python', 'bin', 'python3') }
// 两条流程的入口脚本：fastp 预处理在工作流目录根下，breseq 在 breseq/ 子目录下。
const FASTP_WORKFLOW_METHOD_ID = 'bio-workflow'
const BRESEQ_WORKFLOW_METHOD_ID = 'bio-breseq-workflow'
const SUPPORTED_COMPUTE_METHOD_IDS = new Set<string>([FASTP_WORKFLOW_METHOD_ID, BRESEQ_WORKFLOW_METHOD_ID])
function computeWrapperPath(methodId: string): string { return methodId === BRESEQ_WORKFLOW_METHOD_ID ? join(computeResourceRoot(), 'workflow', 'breseq', 'wrapper.py') : join(computeResourceRoot(), 'workflow', 'wrapper.py') }
// 只有 fastp 那条把判定与主处理放在原生层；breseq 那条是纯 Python（比对、调用、注释都在 Python 侧），
// 所以不能对每条流程都要求原生库存在。
function computeRequiresNativeLibrary(methodId: string): boolean { return methodId === FASTP_WORKFLOW_METHOD_ID }
function queuePresetsPath(): string { return join(computeResourceRoot(), 'workflow', 'queue-presets.json') }
function computeNativeLibraryPath(): string { return join(computeResourceRoot(), 'bio_analysis_function', 'common', 'native', 'lib', process.platform === 'win32' ? 'bio_native.dll' : process.platform === 'darwin' ? 'libbio_native.dylib' : 'libbio_native.so') }
function normalizeComputePath(value: unknown, label: string): string { if (typeof value !== 'string' || !value.trim()) throw new Error(`${label}不能为空`); return resolve(value.trim()) }
async function prepareComputeInput(input: ComputeJobInput): Promise<{ input: ComputeJobInput; htmlPath: string; logDir: string }> {
  const read1Path = normalizeComputePath(input.read1Path, 'R1输入路径')
  if (!existsSync(read1Path)) throw new Error('R1输入 FASTQ 文件不存在')
  const read2Path = input.read2Path?.trim() ? normalizeComputePath(input.read2Path, 'R2输入路径') : undefined
  if (read2Path && !existsSync(read2Path)) throw new Error('R2输入 FASTQ 文件不存在')
  const output1Path = normalizeComputePath(input.output1Path, 'R1输出路径')
  const output2Path = input.output2Path?.trim() ? normalizeComputePath(input.output2Path, 'R2输出路径') : undefined
  const paths = [read1Path, read2Path, output1Path, output2Path].filter((path): path is string => Boolean(path))
  if (new Set(paths).size !== paths.length) throw new Error('输入与输出路径不能相同，输出路径也不能互相冲突')
  if (output2Path && !read2Path) throw new Error('填写 R2 输出时必须同时填写 R2 输入')
  if (read2Path && !output2Path) throw new Error('填写 R2 输入时必须同时填写 R2 输出')
  await mkdir(dirname(output1Path), { recursive: true })
  if (output2Path) await mkdir(dirname(output2Path), { recursive: true })
  const jobDir = join(dirname(output1Path), '.idea-workflow', createRunId())
  await mkdir(jobDir, { recursive: true })
  return { input: { ...input, read1Path, ...(read2Path ? { read2Path } : {}), output1Path, ...(output2Path ? { output2Path } : {}) }, htmlPath: join(jobDir, 'report.html'), logDir: jobDir }
}
// breseq 那条流程的输入形状不同：参考（可多文件）+ reads + **一个产物目录**（产物文件名固定，
// 因为它们是互相引用的一组文件）。两份报告写在 `<产物目录>/.idea-workflow/<任务 id>/` 下，
// 与 fastp 那条写在输出文件旁边的做法一致。
async function prepareBreseqInput(input: ComputeJobInput): Promise<{ input: ComputeJobInput; htmlPath: string; logDir: string }> {
  const referencePaths = (input.referencePath ?? '').split(/[；;,]/).map((piece) => piece.trim()).filter(Boolean)
  if (!referencePaths.length) throw new Error('参考文件不能为空（多个文件用分号分隔）')
  const references = referencePaths.map((piece) => normalizeComputePath(piece, '参考文件'))
  for (const path of references) if (!existsSync(path)) throw new Error(`参考文件不存在：${path}`)
  const read1Path = normalizeComputePath(input.read1Path, 'reads 输入路径（R1）')
  if (!existsSync(read1Path)) throw new Error('reads 输入 FASTQ 文件不存在（R1）')
  const read2Path = input.read2Path?.trim() ? normalizeComputePath(input.read2Path, 'reads 输入路径（R2）') : undefined
  if (read2Path && !existsSync(read2Path)) throw new Error('reads 输入 FASTQ 文件不存在（R2）')
  const outputDir = normalizeComputePath(input.outputDir, '产物目录')
  if ([...references, read1Path, ...(read2Path ? [read2Path] : [])].includes(outputDir)) throw new Error('产物目录不能与输入文件相同')
  await mkdir(outputDir, { recursive: true })
  const jobDir = join(outputDir, '.idea-workflow', createRunId())
  await mkdir(jobDir, { recursive: true })
  return { input: { ...input, referencePath: references.join('；'), read1Path, ...(read2Path ? { read2Path } : {}), outputDir }, htmlPath: join(jobDir, 'report.html'), logDir: jobDir }
}
function startComputeJob(job: ComputeJob, input: ComputeJobInput, htmlPath: string, logDir: string): void {
  const session: ComputeSession = { cancelled: false }; computeSessions.set(job.id, session)
  const root = computeResourceRoot(); const wrapper = computeWrapperPath(job.methodId); const native = computeNativeLibraryPath(); const python = computePythonExecutable()
  if (!existsSync(wrapper)) { failComputeJob(job.id, `未找到 workflow wrapper：${wrapper}`); return }
  if (computeRequiresNativeLibrary(job.methodId) && !existsSync(native)) { failComputeJob(job.id, `未找到 bio workflow native library：${native}`); return }
  if (!isDevelopment && !existsSync(python)) { failComputeJob(job.id, `未找到打包 Python runtime：${python}`); return }
  job.status = 'running'; computeJobs.set(job.id, job); addComputeEvent(job.id, 'progress', 'workflow 已启动', 0)
  const child = spawn(python, ['-u', wrapper], { cwd: root, shell: false, windowsHide: true, env: minimalChildEnv() }); session.child = child
  let stderr = ''
  const finish = (status: ComputeJobStatus, error?: string, result?: ComputeJobResult) => { if (computeSessions.get(job.id) !== session) return; computeSessions.delete(job.id); const current = computeJobs.get(job.id)!; current.status = status; current.progress = status === 'completed' ? 1 : current.progress; if (error) current.error = error; computeJobs.set(job.id, current); if (result) computeResults.set(job.id, result); addComputeEvent(job.id, status === 'completed' ? 'completed' : status === 'cancelled' ? 'cancelled' : 'failed', error ?? (status === 'completed' ? 'workflow 执行完成' : 'workflow 执行失败'), current.progress) }
  let output = ''
  child.stdout.on('data', (chunk: Buffer) => { output += chunk.toString() })
  child.stderr.on('data', (chunk: Buffer) => { stderr = (stderr + chunk.toString()).slice(-MAX_COMPUTE_STDERR) })
  child.once('error', (error) => { if (!session.cancelled) finish('failed', `${error.message}${stderr ? `：${stderr}` : ''}`) })
  child.once('close', (code) => { if (session.cancelled) { finish('cancelled', 'workflow 已取消'); return } if (code !== 0) { finish('failed', stderr || `workflow 进程退出码 ${code ?? -1}`); return } try { const body = JSON.parse(output) as { ok?: boolean; outcome?: unknown; outputs?: string[]; html?: string | null; log?: string | null; error?: { message?: string } }; if (!body.ok) throw new Error(body.error?.message || 'workflow 返回失败'); finish('completed', undefined, { jobId: job.id, status: 'available', outcome: body.outcome, outputs: body.outputs, html: body.html ?? htmlPath, log: body.log ?? join(logDir, 'workflow.json') }) } catch (error) { finish('failed', error instanceof Error ? error.message : String(error)) } })
  child.stdin.end(JSON.stringify({ ...input, htmlPath, logDir }))
}
function failComputeJob(jobId: string, message: string): void { const job = computeJobs.get(jobId); if (!job) return; job.status = 'failed'; job.error = message; computeJobs.set(jobId, job); addComputeEvent(jobId, 'failed', message, job.progress); computeSessions.delete(jobId) }
async function createComputeJob(methodId: string, input: ComputeJobInput): Promise<ComputeJob> {
  if (!SUPPORTED_COMPUTE_METHOD_IDS.has(methodId)) throw new Error(`当前仅支持 ${[...SUPPORTED_COMPUTE_METHOD_IDS].join(' / ')} 的真实执行`)
  if (!input || typeof input !== 'object' || Array.isArray(input) || Object.values(input).some((value) => typeof value !== 'string')) throw new Error('workflow 输入必须是 string record')
  const prepared = methodId === BRESEQ_WORKFLOW_METHOD_ID ? await prepareBreseqInput(input) : await prepareComputeInput(input)
  const job: ComputeJob = { id: `compute-${createRunId()}`, methodId, methodVersion: '0.1.0', status: 'queued', progress: 0, createdAt: new Date().toISOString() }; computeJobs.set(job.id, job); computeEvents.set(job.id, []); addComputeEvent(job.id, 'created', '计算任务已创建', 0); startComputeJob(job, prepared.input, prepared.htmlPath, prepared.logDir); return job
}

const TEXT_EXTENSIONS = new Set(['.md', '.mdx', '.txt', '.json', '.yaml', '.yml', '.ts', '.tsx', '.js', '.jsx', '.css', '.html', '.py', '.c', '.cc', '.cpp', '.cxx', '.go', '.java', '.rs'])
