// 子进程只继承运行解释器/编译器所需的最小系统环境，绝不把用户环境中的密钥、凭据或自定义变量传给被执行的代码。
const CHILD_ENV_ALLOWLIST = new Set([
  'PATH', 'PATHEXT', 'COMSPEC', 'SystemRoot', 'WINDIR', 'TEMP', 'TMP',
  'USERPROFILE', 'HOMEDRIVE', 'HOMEPATH', 'LANG', 'LANGUAGE', 'LC_ALL',
  'NUMBER_OF_PROCESSORS', 'PROCESSOR_ARCHITECTURE', 'PROCESSOR_ARCHITEW6432',
  'PROCESSOR_IDENTIFIER', 'PROCESSOR_LEVEL', 'PROCESSOR_REVISION', 'OS',
  'APPDATA', 'LOCALAPPDATA', 'ProgramData', 'ProgramFiles', 'ProgramFiles(x86)',
  'CommonProgramFiles', 'CommonProgramFiles(x86)',
])
function minimalChildEnv(): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = {}
  for (const key of CHILD_ENV_ALLOWLIST) {
    const value = process.env[key]
    if (value !== undefined) env[key] = value
  }
  return env
}
