function serviceConfigPath(): string { return join(app.getPath('userData'), 'service-config.json') }
function localModelConfigPath(): string { return join(app.getPath('userData'), 'local-model.json') }
function localModelApiKeysPath(): string { return join(app.getPath('userData'), 'local-model-api-keys.json') }
function localExtensionsPath(): string { return join(app.getPath('userData'), 'local-extensions.json') }
function officialModelsPath(): string { return isDevelopment ? resolve(currentDir, '..', 'config', 'official-models.json') : join(process.resourcesPath, 'config', 'official-models.json') }
async function readOfficialModels(): Promise<ModelDescriptor[]> { try { const official = JSON.parse(await readFile(officialModelsPath(), 'utf8')) as { models?: Array<{ id?: string; name?: string; display_name?: string; provider?: string; base_url?: string; model?: string; description?: string; enabled?: boolean }> }; return (official.models ?? []).filter((item) => item.enabled !== false && item.id && item.base_url && item.model).map((item) => ({ id: item.id!, name: item.name ?? item.id!, displayName: item.display_name ?? item.name ?? item.id!, provider: item.provider ?? 'openai-compatible', baseUrl: item.base_url!.replace(/\/+$/, ''), model: item.model!, description: item.description, official: true })) } catch { return [] } }
async function loadLocalModelApiKeys(): Promise<LocalModelApiKeys> { try { const stored = JSON.parse(await readFile(localModelApiKeysPath(), 'utf8')) as unknown; return stored && typeof stored === 'object' ? Object.fromEntries(Object.entries(stored).filter(([id, value]) => typeof id === 'string' && typeof value === 'string')) : {} } catch { return {} } }
async function loadLocalModelConfig(): Promise<StoredLocalModelConfig> { const apiKeys = await loadLocalModelApiKeys(); try { const stored = JSON.parse(await readFile(localModelConfigPath(), 'utf8')) as Partial<StoredLocalModelConfig>; const id = typeof stored.id === 'string' ? stored.id : 'custom'; return { id, name: typeof stored.name === 'string' ? stored.name : stored.model ?? '', displayName: typeof stored.displayName === 'string' ? stored.displayName : stored.model ?? '', provider: typeof stored.provider === 'string' ? stored.provider : 'openai-compatible', baseUrl: typeof stored.baseUrl === 'string' ? stored.baseUrl : '', model: typeof stored.model === 'string' ? stored.model : '', description: stored.description, official: Boolean(stored.official), configured: Boolean(stored.baseUrl && stored.model), hasApiKey: Boolean(apiKeys[id]) } } catch { const models = await readOfficialModels(); const selected = models[0]; if (!selected) return { id: 'custom', name: '', displayName: '', provider: 'openai-compatible', baseUrl: '', model: '', official: false, configured: false, hasApiKey: false }; return { ...selected, configured: true, hasApiKey: Boolean(apiKeys[selected.id]) } } }
function publicLocalModelConfig(config: StoredLocalModelConfig): LocalModelConfig { return { ...config, configured: Boolean(config.baseUrl && config.model), hasApiKey: config.hasApiKey } }
async function saveLocalModelConfig(input: { id?: string; name?: string; displayName?: string; provider?: string; baseUrl: string; model: string; apiKey: string }): Promise<LocalModelConfig> { const baseUrl = input.baseUrl.trim().replace(/\/+$/, ''); const model = input.model.trim(); if (!baseUrl || !model) throw new Error('本地模型地址和模型名不能为空'); const current = await loadLocalModelConfig(); const official = (await readOfficialModels()).find((item) => item.id === input.id); const id = input.id?.trim() || official?.id || current.id || `custom-${Date.now()}`; const apiKeys = await loadLocalModelApiKeys(); const apiKey = input.apiKey.trim(); if (apiKey) { if (!safeStorage.isEncryptionAvailable()) throw new Error('当前系统无法安全保存本地模型 API Key'); apiKeys[id] = safeStorage.encryptString(apiKey).toString('base64'); } const stored: StoredLocalModelConfig = { ...(official ?? { id, name: input.name?.trim() || model, displayName: input.displayName?.trim() || model, provider: input.provider?.trim() || 'openai-compatible', description: undefined, official: false }), baseUrl, model, configured: true, hasApiKey: Boolean(apiKeys[id]) }; await mkdir(dirname(localModelConfigPath()), { recursive: true }); await writeFile(localModelConfigPath(), JSON.stringify(stored), 'utf8'); await writeFile(localModelApiKeysPath(), JSON.stringify(apiKeys), 'utf8'); return publicLocalModelConfig(stored) }
async function localModelApiKey(modelId: string): Promise<string> { const encrypted = (await loadLocalModelApiKeys())[modelId]; return encrypted && safeStorage.isEncryptionAvailable() ? safeStorage.decryptString(Buffer.from(encrypted, 'base64')) : '' }
async function writeServiceConfig(config: StoredServiceConfig): Promise<void> {
  const path = serviceConfigPath()
  const temporaryPath = `${path}.tmp-${process.pid}-${crypto.randomUUID()}`
  await mkdir(dirname(path), { recursive: true })
  try {
    await writeFile(temporaryPath, JSON.stringify(config), 'utf8')
    await rename(temporaryPath, path)
  } catch (error) {
    await unlink(temporaryPath).catch(() => undefined)
    throw error
  }
}

async function migrateLegacyOwnerSession(): Promise<void> {
  if (!isOwnerClient) return
  const targetPath = serviceConfigPath()
  const legacyPath = join(legacyUserDataPath, 'service-config.json')
  const targetLocalStatePath = join(app.getPath('userData'), 'Local State')
  const legacyLocalStatePath = join(legacyUserDataPath, 'Local State')
  const markerPath = join(app.getPath('userData'), 'session-migration-v1')
  if (targetPath === legacyPath || existsSync(targetPath) || existsSync(markerPath) || !existsSync(legacyPath)) return
  try { await mkdir(dirname(targetPath), { recursive: true }); if (!existsSync(targetLocalStatePath) && existsSync(legacyLocalStatePath)) await copyFile(legacyLocalStatePath, targetLocalStatePath); await copyFile(legacyPath, targetPath); await writeFile(markerPath, 'migrated\n', { flag: 'wx' }) } catch (error) { logger.warn('Failed to migrate legacy Owner session', error) }
}
function createDeviceId(): string { return `desktop-${crypto.randomUUID()}` }
async function loadServiceConfig(): Promise<StoredServiceConfig> { try { const stored = JSON.parse(await readFile(serviceConfigPath(), 'utf8')) as Partial<StoredServiceConfig>; return { serverUrl: isDevelopment && typeof stored.serverUrl === 'string' && stored.serverUrl.trim() ? stored.serverUrl : DEFAULT_SERVICE_URL, spaceId: typeof stored.spaceId === 'string' ? stored.spaceId : '', deviceId: typeof stored.deviceId === 'string' && stored.deviceId ? stored.deviceId : createDeviceId(), signedIn: Boolean(stored.encryptedRefreshToken), route: typeof stored.route === 'string' ? stored.route : undefined, encryptedAccessToken: typeof stored.encryptedAccessToken === 'string' ? stored.encryptedAccessToken : undefined, encryptedRefreshToken: typeof stored.encryptedRefreshToken === 'string' ? stored.encryptedRefreshToken : undefined } } catch { return { serverUrl: DEFAULT_SERVICE_URL, spaceId: '', deviceId: createDeviceId(), signedIn: false } } }
function publicServiceConfig(config: StoredServiceConfig): ServiceConfig { return { serverUrl: config.serverUrl, spaceId: config.spaceId, deviceId: config.deviceId, signedIn: Boolean(config.encryptedRefreshToken), route: config.route } }
async function saveServiceConfig(config: { spaceId: string }): Promise<ServiceConfig> { const current = await loadServiceConfig(); const stored: StoredServiceConfig = { ...current, serverUrl: DEFAULT_SERVICE_URL, spaceId: config.spaceId.trim(), signedIn: Boolean(current.encryptedRefreshToken) }; await writeServiceConfig(stored); return publicServiceConfig(stored) }
function decryptSecret(value: string | undefined): string { if (!value || !safeStorage.isEncryptionAvailable()) throw new Error('请先完成账号登录'); return safeStorage.decryptString(Buffer.from(value, 'base64')) }
async function saveLoginSession(config: StoredServiceConfig, payload: { access_token: string; refresh_token: string; route: string }): Promise<ServiceConfig> { if (!safeStorage.isEncryptionAvailable()) throw new Error('当前系统无法安全保存登录会话'); const stored: StoredServiceConfig = { ...config, signedIn: true, route: payload.route, encryptedAccessToken: safeStorage.encryptString(payload.access_token).toString('base64'), encryptedRefreshToken: safeStorage.encryptString(payload.refresh_token).toString('base64') }; await writeServiceConfig(stored); return publicServiceConfig(stored) }
async function rawServiceRequest(config: StoredServiceConfig, path: string, init: RequestInit = {}, accessToken?: string, timeoutMs = 15_000): Promise<Response> { const headers = new Headers(init.headers); headers.set('X-Device-ID', config.deviceId); if (config.spaceId) headers.set('X-Space-ID', config.spaceId); if (accessToken) headers.set('Authorization', `Bearer ${accessToken}`); const controller = new AbortController(); const timeout = setTimeout(() => controller.abort(), timeoutMs); try { return await fetch(`${config.serverUrl}${path}`, { ...init, headers, signal: controller.signal }) } catch (error) { const detail = error instanceof Error && error.name === 'AbortError' ? '请求 IDEA 服务超时' : error instanceof Error && error.message ? `无法连接 IDEA 服务：${error.message}` : '无法连接 IDEA 服务'; throw new Error(detail) } finally { clearTimeout(timeout) } }
async function clearLocalSession(config: StoredServiceConfig): Promise<void> { await writeServiceConfig({ serverUrl: DEFAULT_SERVICE_URL, spaceId: config.spaceId, deviceId: config.deviceId, signedIn: false }) }
async function refreshAccessToken(config: StoredServiceConfig, generation: number): Promise<StoredServiceConfig> { if (refreshPromise) return refreshPromise; const pending = (async () => { const latest = await loadServiceConfig(); if (generation !== authGeneration || !latest.encryptedRefreshToken) throw new Error('登录会话已失效，请重新登录'); const response = await rawServiceRequest(latest, '/api/auth/refresh', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ refresh_token: decryptSecret(latest.encryptedRefreshToken) }) }); const body = await response.json().catch(() => ({})) as { detail?: string; access_token?: string; refresh_token?: string; route?: string }; if (!response.ok || !body.access_token || !body.refresh_token || !body.route) { if (generation === authGeneration) await clearLocalSession(latest); throw new Error(body.detail || '登录会话已失效，请重新登录') } if (generation !== authGeneration) throw new Error('登录会话已失效，请重新登录'); await saveLoginSession(latest, { access_token: body.access_token, refresh_token: body.refresh_token, route: body.route }); authGeneration += 1; return loadServiceConfig() })(); refreshPromise = pending; try { return await pending } finally { if (refreshPromise === pending) refreshPromise = undefined } }
async function serviceRequest(path: string, init: RequestInit = {}, requireAuthentication = false, timeoutMs = 15_000): Promise<Response> { const config = await loadServiceConfig(); const generation = authGeneration; const accessToken = requireAuthentication ? decryptSecret(config.encryptedAccessToken) : undefined; const response = await rawServiceRequest(config, path, init, accessToken, timeoutMs); if (!requireAuthentication || response.status !== 401) return response; const refreshed = await refreshAccessToken(config, generation); return rawServiceRequest(refreshed, path, init, decryptSecret(refreshed.encryptedAccessToken), timeoutMs) }
function normalizeContextBlocks(value: unknown): ContextBlock[] { if (!Array.isArray(value)) throw new Error('上下文块必须是数组'); let length = 0; return value.map((block) => { if (!block || typeof block !== 'object') throw new Error('上下文块无效'); const { path, name, content } = block as Partial<ContextBlock>; if (typeof path !== 'string' || typeof name !== 'string' || typeof content !== 'string') throw new Error('上下文块无效'); length += content.length; if (length > MAX_CONTEXT_BLOCKS_LENGTH) throw new Error(`上下文内容不能超过 ${MAX_CONTEXT_BLOCKS_LENGTH} 个字符`); return { path, name, content } }) }
async function passwordLogin(email: string, password: string): Promise<LoginResponse> { authGeneration += 1; const config = await loadServiceConfig(); const response = await serviceRequest('/api/auth/password/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email, password }) }); const body = await response.json().catch(() => ({})) as { detail?: string; access_token?: string; refresh_token?: string; route?: string; principal?: { account_id: string; role: string } }; if (!response.ok || !body.access_token || !body.refresh_token || !body.route || !body.principal) throw new Error(body.detail || '登录失败'); await saveLoginSession(config, { access_token: body.access_token, refresh_token: body.refresh_token, route: body.route }); return { route: body.route, principal: body.principal } }
// #region debug-point B:logout-main
function reportLogoutDebug(msg: string, data: Record<string, unknown>): void { void fetch('http://127.0.0.1:7777/event', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ sessionId: 'logout-recovery', runId: 'pre-fix', hypothesisId: 'B', location: 'electron/main.ts', msg: `[DEBUG] ${msg}`, data, ts: Date.now() }) }).catch(() => undefined) }
// #endregion
async function logout(): Promise<void> { if (logoutPromise) return logoutPromise; const pending = (async () => { authGeneration += 1; const config = await loadServiceConfig(); reportLogoutDebug('logout IPC started', { hasRefreshToken: Boolean(config.encryptedRefreshToken), signedIn: config.signedIn }); if (config.encryptedRefreshToken) await rawServiceRequest(config, '/api/auth/logout', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ refresh_token: decryptSecret(config.encryptedRefreshToken) }) }).catch((error) => reportLogoutDebug('remote logout failed but local cleanup continues', { error: error instanceof Error ? error.message : String(error) })); await clearLocalSession(config); reportLogoutDebug('local logout state persisted', { path: serviceConfigPath() }) })(); logoutPromise = pending; try { await pending } finally { if (logoutPromise === pending) logoutPromise = undefined } }
function localRuntimeCapabilities(): DeviceRuntime['capabilities'] { return { workspace: true, terminal: true, local_models: true, gpu: false, browser: false, computer: false, mcp: isOwnerClient, plugins: false } }
async function registerLocalRuntime(): Promise<DeviceRuntime> { const response = await serviceRequest('/api/runtimes/register', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ runtime_kind: isOwnerClient ? 'owner_desktop' : 'desktop', capabilities: localRuntimeCapabilities() }) }, true); const body = await response.json().catch(() => ({})) as Partial<DeviceRuntime> & { detail?: string }; if (!response.ok || !body.id || !body.status) throw new Error(body.detail || '本地 Runtime 注册失败'); return body as DeviceRuntime }
async function heartbeatLocalRuntime(): Promise<DeviceRuntime> { const response = await serviceRequest('/api/runtimes/heartbeat', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ runtime_kind: isOwnerClient ? 'owner_desktop' : 'desktop' }) }, true); if (response.status === 404) return registerLocalRuntime(); const body = await response.json().catch(() => ({})) as Partial<DeviceRuntime> & { detail?: string }; if (!response.ok || !body.id || !body.status) throw new Error(body.detail || '本地 Runtime 心跳失败'); return body as DeviceRuntime }

function compareVersions(left: string, right: string): number { const a = left.match(SEMVER); const b = right.match(SEMVER); if (!a || !b) throw new Error('版本号无效'); for (let index = 1; index <= 3; index += 1) { if (Number(a[index]) !== Number(b[index])) return Number(a[index]) > Number(b[index]) ? 1 : -1 } const ap = a[4]; const bp = b[4]; if (!ap || !bp) return ap ? -1 : bp ? 1 : 0; const aa = ap.split('.'); const bb = bp.split('.'); for (let index = 0; index < Math.max(aa.length, bb.length); index += 1) { if (aa[index] === undefined) return -1; if (bb[index] === undefined) return 1; if (aa[index] === bb[index]) continue; const ai = /^\d+$/.test(aa[index]); const bi = /^\d+$/.test(bb[index]); if (ai && bi) return Number(aa[index]) > Number(bb[index]) ? 1 : -1; return ai ? -1 : bi ? 1 : aa[index] > bb[index] ? 1 : -1 } return 0 }
function asUpdateError(error: unknown): UpdateStatus { return { state: 'error', message: error instanceof Error ? error.message.slice(0, 160) : '更新服务不可用' } }
async function checkForUpdates(): Promise<UpdateStatus> { try { updateStatus = { state: 'checked' }; const response = await fetch(`${UPDATE_ORIGIN}/static/updates/${UPDATE_FLAVOR}/latest.json`); if (response.status === 404) return updateStatus = { state: 'current' }; if (!response.ok) throw new Error('更新检查失败'); const manifest = await response.json() as Record<string, unknown>; const version = typeof manifest.version === 'string' ? manifest.version : ''; const releaseNotes = typeof manifest.releaseNotes === 'string' ? manifest.releaseNotes : ''; const publishedAt = typeof manifest.publishedAt === 'string' ? manifest.publishedAt : ''; const downloadUrl = typeof manifest.downloadUrl === 'string' ? manifest.downloadUrl : ''; const sha256 = typeof manifest.sha256 === 'string' ? manifest.sha256 : ''; const fileName = typeof manifest.fileName === 'string' ? manifest.fileName : ''; const prefix = `/static/updates/${UPDATE_FLAVOR}/`; const url = new URL(downloadUrl, UPDATE_ORIGIN); if (manifest.flavor !== UPDATE_FLAVOR || !SEMVER.test(version) || !releaseNotes || !publishedAt || !fileName || !/^[a-f0-9]{64}$/i.test(sha256) || url.origin !== UPDATE_ORIGIN || !url.pathname.startsWith(prefix) || url.pathname !== `${prefix}${fileName}` || fileName !== basename(fileName) || !fileName.toLowerCase().endsWith('.exe')) throw new Error('更新清单无效'); if (compareVersions(version, app.getVersion()) <= 0) return updateStatus = { state: 'current' }; const info = { version, releaseNotes, publishedAt }; availableUpdate = { downloadUrl: url.toString(), sha256: sha256.toLowerCase(), fileName, info }; return updateStatus = { state: 'available', update: info } } catch (error) { availableUpdate = undefined; return updateStatus = asUpdateError(error) } }
async function downloadAndInstallUpdate(): Promise<UpdateStatus> { if (process.platform !== 'win32') return updateStatus = { state: 'error', message: '当前系统不支持自动安装更新' }; if (!availableUpdate) return updateStatus = { state: 'error', message: '请先检查更新' }; try { updateStatus = { state: 'downloading', update: availableUpdate.info }; const response = await fetch(availableUpdate.downloadUrl); if (!response.ok) throw new Error('更新下载安装包失败'); const buffer = Buffer.from(await response.arrayBuffer()); if (createHash('sha256').update(buffer).digest('hex') !== availableUpdate.sha256) throw new Error('更新包校验失败'); const directory = join(app.getPath('temp'), 'project-idea-updates', UPDATE_FLAVOR); await mkdir(directory, { recursive: true }); const installerPath = join(directory, availableUpdate.fileName); await writeFile(installerPath, buffer); const scriptPath = join(directory, `install-${process.pid}-${Date.now()}.cmd`); const script = `@echo off\r\n:wait\r\ntasklist /FI "PID eq ${process.pid}" /NH | find "${process.pid}" >nul\r\nif not errorlevel 1 ( timeout /t 1 /nobreak >nul & goto wait )\r\n"${installerPath}" /S\r\nstart "" "${process.execPath}"\r\ndel "%~f0"\r\n`; await writeFile(scriptPath, script, 'utf8'); const child = spawn('cmd.exe', ['/c', scriptPath], { detached: true, stdio: 'ignore', windowsHide: true }); child.unref(); updateStatus = { state: 'downloaded', update: availableUpdate.info }; app.quit(); return updateStatus } catch (error) { return updateStatus = asUpdateError(error) } }

async function transitionLocalHandoff(handoffId: string, status: 'accepted' | 'running' | 'completed' | 'failed' | 'cancelled', runtimeId: string, error = ''): Promise<void> {
  const response = await serviceRequest(`/api/handoffs/${encodeURIComponent(handoffId)}/${status}`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ runtime_id: runtimeId, error }) }, true)
  if (!response.ok) { const body = await response.json().catch(() => ({})) as { detail?: string }; throw new Error(body.detail || '任务交接状态更新失败') }
}
async function executeApprovedHandoff(handoffId: string, workspace: string, send: (event: RunEvent) => void): Promise<{ sessionId: string }> {
  if (!workspace || !existsSync(workspace)) throw new Error('请选择有效的本地工作区')
  const runtime = await heartbeatLocalRuntime()
  const response = await serviceRequest(`/api/handoffs/${encodeURIComponent(handoffId)}/execution?runtime_id=${encodeURIComponent(runtime.id)}`, {}, true)
  const body = await response.json().catch(() => ({})) as { detail?: string; manifest?: HandoffExecutionManifest }
  if (!response.ok || !body.manifest || body.manifest.kind !== 'run_file') throw new Error(body.detail || '交接执行清单不可用')
  const manifest = body.manifest
  if (!/^(?!.*(?:^|[\\/])\.\.(?:[\\/]|$))[A-Za-z0-9._\\/-]+$/.test(manifest.relative_path)) throw new Error('交接文件路径无效')
  const filePath = assertWithinWorkspace(workspace, resolve(workspace, manifest.relative_path))
  await transitionLocalHandoff(handoffId, 'accepted', runtime.id)
  const sessionId = `handoff-${handoffId.slice(0, 12)}-${createRunId()}`
  const session = { handoffId, runtimeId: runtime.id, cancelled: false } satisfies HandoffExecutionSession
  handoffSessions.set(sessionId, session)
  try { await transitionLocalHandoff(handoffId, 'running', runtime.id) } catch (error) { handoffSessions.delete(sessionId); await transitionLocalHandoff(handoffId, 'failed', runtime.id, error instanceof Error ? error.message : String(error)).catch(() => undefined); throw error }
  setImmediate(() => { if (session.cancelled) { handoffSessions.delete(sessionId); send({ sessionId, stream: 'system', content: '交接任务已取消。\n', terminal: true }); return } void executeFile(workspace, filePath, manifest.mode, sessionId, send).then(async () => { if (!session.cancelled) await transitionLocalHandoff(handoffId, 'completed', runtime.id); handoffSessions.delete(sessionId); send({ sessionId, stream: 'system', content: session.cancelled ? '交接任务已取消。\n' : '交接任务执行完成。\n', terminal: true }) }).catch(async (error) => { const message = error instanceof Error ? error.message : String(error); if (!session.cancelled) await transitionLocalHandoff(handoffId, 'failed', runtime.id, message).catch(() => undefined); handoffSessions.delete(sessionId); send({ sessionId, stream: session.cancelled ? 'system' : 'stderr', content: `${session.cancelled ? '交接任务已取消。' : message}\n`, terminal: true }) }) })
  return { sessionId }
}

async function streamChat(request: { agentId: string; message: string; contextBlocks?: unknown; conversationId?: string; useMemory?: boolean; modelKey?: ModelKey }, send: (event: { type: string; payload: Record<string, unknown> }) => void): Promise<ChatResponse> {
  const contextBlocks = request.contextBlocks === undefined ? [] : normalizeContextBlocks(request.contextBlocks)
  const body = { agent_id: request.agentId, message: request.message, context_blocks: contextBlocks, conversation_id: request.conversationId, use_memory: request.useMemory === true, model_key: request.modelKey ?? 'gpt' }
  const response = await serviceRequest('/api/assistant/chat/stream', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }, true)
  if (response.status === 404) {
    const fallback = await serviceRequest('/api/assistant/chat', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) }, true)
    const fallbackBody = await fallback.json().catch(() => ({})) as { detail?: string; reply?: string; conversation_id?: string; agent_id?: string; model_key?: ModelKey; run_id?: string }
    if (!fallback.ok || !fallbackBody.reply || !fallbackBody.conversation_id || !fallbackBody.agent_id) throw new Error(fallbackBody.detail || `在线服务请求失败 (${fallback.status})`)
    const result = { reply: fallbackBody.reply, conversationId: fallbackBody.conversation_id, agentId: fallbackBody.agent_id, modelKey: fallbackBody.model_key ?? 'gpt-5.6-terra', runId: fallbackBody.run_id ?? `local-${Date.now()}` }
    send({ type: 'run.started', payload: { run_id: result.runId, conversation_id: result.conversationId, agent_id: result.agentId } })
    send({ type: 'model.text.delta', payload: { run_id: result.runId, content: result.reply } })
    send({ type: 'run.completed', payload: { run_id: result.runId, conversation_id: result.conversationId, agent_id: result.agentId, model_key: result.modelKey, reply: result.reply } })
    return result
  }
  const contentType = response.headers.get('content-type') ?? ''
  if (!response.ok) { const errorBody = await response.json().catch(() => ({})) as { detail?: string }; throw new Error(errorBody.detail || `在线服务请求失败 (${response.status})`) }
  if (!response.body) throw new Error(`在线服务返回空响应 (${response.status}, ${contentType || 'unknown content type'})`)
  if (!contentType.includes('text/event-stream')) {
    const jsonBody = await response.json().catch(() => ({})) as { detail?: string; reply?: string; conversation_id?: string; agent_id?: string; model_key?: ModelKey; run_id?: string }
    if (!jsonBody.reply || !jsonBody.conversation_id || !jsonBody.agent_id) throw new Error(jsonBody.detail || `在线服务返回了无法识别的响应 (${response.status}, ${contentType || 'unknown content type'})`)
    const result = { reply: jsonBody.reply, conversationId: jsonBody.conversation_id, agentId: jsonBody.agent_id, modelKey: jsonBody.model_key ?? 'gpt-5.6-terra', runId: jsonBody.run_id ?? `local-${Date.now()}` }
    send({ type: 'run.started', payload: { run_id: result.runId, conversation_id: result.conversationId, agent_id: result.agentId } })
    send({ type: 'model.text.delta', payload: { run_id: result.runId, content: result.reply } })
    send({ type: 'run.completed', payload: { run_id: result.runId, conversation_id: result.conversationId, agent_id: result.agentId, model_key: result.modelKey, reply: result.reply } })
    return result
  }
  const decoder = new TextDecoder()
  let buffer = ''
  let completed: ChatResponse | undefined
  const emit = (block: string) => {
    const lines = block.split('\n')
    const eventLine = lines.find((line) => line.startsWith('event: '))
    const dataLine = lines.find((line) => line.startsWith('data: '))
    const eventType = eventLine?.slice(7)
    if (!eventType || !dataLine) return
    const payload = JSON.parse(dataLine.slice(6)) as Record<string, unknown>
    send({ type: eventType, payload })
    if (eventType === 'run.completed') completed = { reply: String(payload.reply ?? ''), conversationId: String(payload.conversation_id ?? ''), agentId: String(payload.agent_id ?? request.agentId), modelKey: String(payload.model_key ?? request.modelKey ?? 'gpt-5.6-terra'), runId: String(payload.run_id ?? '') }
    if (eventType === 'run.failed') throw new Error(String(payload.error ?? '运行失败'))
  }
  for await (const chunk of response.body as unknown as AsyncIterable<Uint8Array>) {
    buffer += decoder.decode(chunk, { stream: true })
    let boundary = buffer.indexOf('\n\n')
    while (boundary >= 0) { emit(buffer.slice(0, boundary)); buffer = buffer.slice(boundary + 2); boundary = buffer.indexOf('\n\n') }
  }
  if (buffer.trim()) emit(buffer)
  if (!completed || !completed.reply || !completed.conversationId || !completed.runId) throw new Error('流式聊天未返回完成结果')
  return completed
}

function assertWithinWorkspace(workspace: string, target: string): string { const workspacePath = resolve(workspace); const targetPath = resolve(target); const pathFromWorkspace = relative(workspacePath, targetPath); if (pathFromWorkspace.startsWith('..') || pathFromWorkspace === '' && targetPath !== workspacePath) throw new Error('文件路径不在当前工作区内'); return targetPath }

