function ragProjectDirectory(): string { return isDevelopment ? resolve(currentDir, '..', '..', 'IDEA Assistant', 'resources', 'rag', 'runtime', 'rag_server') : join(process.resourcesPath, 'rag', 'runtime', 'rag_server') }
function ragRuntimeBinary(): string { const runtime = dirname(ragProjectDirectory()); return process.platform === 'win32' ? join(runtime, 'python', 'python.exe') : join(runtime, 'python', 'bin', 'python3') }
function ragModelDirectory(): string { return join(dirname(ragProjectDirectory()), 'rag_model', 'BAAI__bge-small-zh-v1.5') }
function ragUrl(port = RAG_DEFAULT_PORT): string { return `http://127.0.0.1:${port}` }
async function probeRagHealth(): Promise<boolean> { const controller = new AbortController(); const timeout = setTimeout(() => controller.abort(), 1_000); try { const response = await fetch(`${ragUrl()}/api/health`, { signal: controller.signal }); if (!response.ok) return false; const body = await response.json() as { status?: unknown }; return body.status === 'ok' } catch { return false } finally { clearTimeout(timeout) } }
async function waitForRagHealth(): Promise<void> { const deadline = Date.now() + RAG_STARTUP_TIMEOUT_MS; while (Date.now() < deadline) { if (await probeRagHealth()) return; await new Promise((resolveDelay) => setTimeout(resolveDelay, 500)) } throw new Error('RAG 知识库健康检查超时') }
function stopRagRuntime(): void { const child = ragProcess; ragProcess = undefined; ragStartPromise = undefined; ragRuntime = { status: 'stopped' }; if (child && !child.killed) child.kill() }
async function getRagRuntime(): Promise<RagRuntime> { if (await probeRagHealth()) return ragRuntime = { status: 'ready', url: ragUrl() }; if (ragStartPromise) return ragStartPromise; const serverDir = ragProjectDirectory(); const binary = ragRuntimeBinary(); const entryPath = join(serverDir, 'run_rag_server.py'); const modelDir = ragModelDirectory(); if (!existsSync(binary) || !existsSync(entryPath) || !existsSync(modelDir)) return ragRuntime = { status: 'error', error: '未找到内置 RAG 知识库资源' }; ragRuntime = { status: 'starting' }; ragStartPromise = (async () => { const child = spawn(binary, [entryPath, '--port', String(RAG_DEFAULT_PORT)], { cwd: serverDir, shell: false, windowsHide: true, env: { ...minimalChildEnv(), PYTHONDONTWRITEBYTECODE: '1', RAG_EMBEDDING_MODEL: modelDir } }); ragProcess = child; child.stdout.on('data', (chunk) => { const text = chunk.toString(); if (text.includes('Uvicorn running')) ragRuntime = { status: 'ready', url: ragUrl() } }); child.stderr.on('data', (chunk) => { const text = chunk.toString(); if (text.includes('Uvicorn running')) ragRuntime = { status: 'ready', url: ragUrl() } }); child.once('error', (error) => { if (ragProcess === child) { ragProcess = undefined; ragRuntime = { status: 'error', error: `RAG 知识库启动失败：${error.message}` } } }); child.once('exit', () => { if (ragProcess === child) { ragProcess = undefined; if (ragRuntime.status !== 'ready') ragRuntime = { status: 'error', error: 'RAG 知识库进程已退出' } } }); try { await waitForRagHealth(); return ragRuntime = { status: 'ready', url: ragUrl() } } catch (error) { if (ragProcess === child) stopRagRuntime(); return ragRuntime = { status: 'error', error: error instanceof Error ? error.message : 'RAG 知识库启动失败' } } finally { ragStartPromise = undefined } })(); return ragStartPromise }
async function ragRequest<T>(path: string, init: RequestInit = {}): Promise<T> { const runtime = await getRagRuntime(); if (runtime.status !== 'ready' || !runtime.url) throw new Error('RAG 知识库服务未就绪'); const headers = new Headers(init.headers); headers.set('X-API-Key', 'idea-local-admin'); const response = await fetch(`${runtime.url}${path}`, { ...init, headers }); const body = await response.json().catch(() => ({})) as { detail?: string } & T; if (!response.ok) throw new Error(body.detail || `RAG 请求失败 (${response.status})`); return body }
async function ragSearch(collection: string, query: string, topK = 5): Promise<{ query: string; collection: string; total_results: number; results: RagSearchResult[] }> { if (!['public', 'private', 'novel', 'data'].includes(collection)) throw new Error('无效的知识库集合'); if (!query.trim()) throw new Error('请输入检索内容'); return ragRequest('/api/search', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ query: query.trim(), top_k: topK }) }) }
async function ragIngest(filePaths: string[], collection: string): Promise<{ status: string; filename: string; collection: string }[]> { if (!['public', 'private', 'novel', 'data'].includes(collection)) throw new Error('无效的知识库集合'); if (!filePaths.length) return []; const runtime = await getRagRuntime(); if (runtime.status !== 'ready' || !runtime.url) throw new Error('RAG 知识库服务未就绪'); const results: { status: string; filename: string; collection: string }[] = []; for (const filePath of filePaths) { const form = new FormData(); const fileBuffer = await readFile(filePath); form.append('file', new Blob([fileBuffer]), basename(filePath)); const response = await fetch(`${runtime.url}/api/documents/upload?collection=${encodeURIComponent(collection)}`, { method: 'POST', headers: { 'X-API-Key': 'idea-local-admin' }, body: form }); const body = await response.json().catch(() => ({})) as { detail?: string; status?: string; filename?: string; collection?: string }; if (!response.ok || !body.filename) throw new Error(body.detail || '文档上传失败'); results.push({ status: 'ok', filename: body.filename, collection: body.collection ?? collection }) } await ragRequest('/api/admin/rebuild?collection=all', { method: 'POST' }).catch(() => undefined); return results }

async function literatureRequest<T>(path: string, init: RequestInit = {}, timeoutMs = 15_000): Promise<T> { const response = await serviceRequest(path, init, true, timeoutMs); const body = await response.json().catch(() => ({})) as { detail?: string } & T; if (!response.ok) throw new Error(body.detail || `文献服务请求失败 (${response.status})`); return body }
function normalizeLiteratureItem(value: unknown): LiteraturePaper { if (!value || typeof value !== 'object') throw new Error('文献服务返回了无效条目'); const item = value as Record<string, unknown>; const literatureId = item.literature_id ?? item.paper_id ?? item.id; if (typeof literatureId !== 'string' || typeof item.title !== 'string') throw new Error('文献服务返回了无效条目'); const authorsValue = item.authors ?? item.author; const authors = Array.isArray(authorsValue) ? authorsValue.filter((author): author is string => typeof author === 'string') : typeof authorsValue === 'string' ? authorsValue.split(/[,;，；]/).map((author) => author.trim()).filter(Boolean) : []; const numberOrNull = (candidate: unknown): number | null => { const numeric = typeof candidate === 'number' ? candidate : typeof candidate === 'string' && candidate.trim() ? Number(candidate) : null; return typeof numeric === 'number' && Number.isFinite(numeric) ? numeric : null }; return { literature_id: literatureId, title: item.title, authors, source: typeof item.source === 'string' ? item.source : '', venue: typeof item.venue === 'string' ? item.venue : '', date: typeof item.date === 'string' ? item.date : typeof item.published_at === 'string' ? item.published_at : '', abstract: typeof item.abstract === 'string' ? item.abstract : '', score: numberOrNull(item.score ?? item.relevance_score), authority: numberOrNull(item.authority), url: typeof item.url === 'string' ? item.url : '', download_url: typeof item.download_url === 'string' ? item.download_url : null } }
async function listLiterature(limit = 50, offset = 0): Promise<LiteratureListResponse> { const body = await literatureRequest<{ items?: unknown[]; papers?: unknown[]; total?: unknown }>(`/api/platform/literature?limit=${Math.max(1, Math.min(100, Math.floor(limit)))}&offset=${Math.max(0, Math.floor(offset))}`); const items = body.items ?? body.papers; if (!Array.isArray(items)) throw new Error('文献服务返回了无效列表'); return { items: items.map(normalizeLiteratureItem), total: typeof body.total === 'number' ? body.total : items.length } }
async function getLiteratureResearchDirection(): Promise<LiteratureResearchDirection> { const body = await literatureRequest<{ content?: unknown; research_direction?: unknown }>('/api/platform/literature/research-direction'); const content = body.content ?? body.research_direction; return { content: typeof content === 'string' ? content : null } }
async function saveLiteratureResearchDirection(direction: string): Promise<LiteratureResearchDirection> { const body = await literatureRequest<{ content?: unknown; research_direction?: unknown }>('/api/platform/literature/research-direction', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ content: direction.trim() }) }); const content = body.content ?? body.research_direction; return { content: typeof content === 'string' ? content : direction.trim() } }
async function collectLiterature(): Promise<unknown> { return literatureRequest('/api/platform/literature/collect', { method: 'POST' }, LITERATURE_COLLECT_TIMEOUT_MS) }
function literatureDownloadName(response: Response, literatureId: string): string { const match = (response.headers.get('content-disposition') ?? '').match(/filename\*?=(?:UTF-8''|\"?)([^;\"]+)/i)?.[1]; if (!match) return `${literatureId}.pdf`; try { return basename(decodeURIComponent(match.replace(/^\"|\"$/g, ''))) || `${literatureId}.pdf` } catch { return `${literatureId}.pdf` } }
async function downloadLiterature(literatureId: string): Promise<LiteratureDownloadResult> { if (!literatureId.trim()) throw new Error('文献标识无效'); const response = await serviceRequest(`/api/platform/literature/${encodeURIComponent(literatureId)}/download`, {}, true, LITERATURE_DOWNLOAD_TIMEOUT_MS); if (!response.ok) { const body = await response.json().catch(() => ({})) as { detail?: string }; throw new Error(body.detail || `文献下载失败 (${response.status})`) } const buffer = Buffer.from(await response.arrayBuffer()); if (!buffer.length) throw new Error('文献下载返回空文件'); const result = await dialog.showSaveDialog({ title: '保存论文 PDF', defaultPath: literatureDownloadName(response, literatureId), filters: [{ name: 'PDF 文档', extensions: ['pdf'] }, { name: '所有文件', extensions: ['*'] }] }); if (result.canceled || !result.filePath) return { saved: false, canceled: true }; await writeFile(result.filePath, buffer); return { saved: true, path: result.filePath } }
function assertTrustedSender(event: Electron.IpcMainInvokeEvent): void { const frameUrl = event.senderFrame?.url ?? event.sender.getURL(); const allowed = isDevelopment ? frameUrl.startsWith('http://127.0.0.1:5173') : frameUrl.startsWith('file://'); if (!allowed) throw new Error('拒绝来自未授权页面的 IPC 调用') }
async function localChatStream(request: { agentId: string; message: string; contextBlocks?: Array<{ path: string; name: string; content: string }>; conversationId?: string; useMemory?: boolean; modelKey?: ModelKey }, send: (event: { type: string; payload: Record<string, unknown> }) => void): Promise<ChatResponse> { const config = await loadLocalModelConfig(); if (!config.configured) throw new Error('请先在设置中配置模型'); const runId = `local-${createRunId()}`; const conversationId = request.conversationId ?? `local-conversation-${Date.now()}`; send({ type: 'run.started', payload: { runtime: 'local', run_id: runId, conversation_id: conversationId, agent_id: request.agentId, model_key: config.id } }); const headers = new Headers({ 'Content-Type': 'application/json' }); const apiKey = await localModelApiKey(config.id); if (apiKey) headers.set('Authorization', `Bearer ${apiKey}`); const context = (request.contextBlocks ?? []).map((block) => `文件：${block.path}\n${block.content}`).join('\n\n'); const endpoint = /\/chat\/completions\/?$/.test(config.baseUrl) ? config.baseUrl : `${config.baseUrl}/chat/completions`; let response: Response; try { response = await fetch(endpoint, { method: 'POST', headers, body: JSON.stringify({ model: config.model, stream: true, messages: [{ role: 'system', content: '你是 IDEA Assistant 的本地 Agent。优先使用给定的本地工作区上下文，必要时明确说明限制。' }, ...(context ? [{ role: 'user', content: `本地上下文：\n${context}` }] : []), { role: 'user', content: request.message }] }) }) } catch (error) { throw new Error(`无法连接本地模型：${endpoint}（${error instanceof Error ? error.message : String(error)}）`) }; if (!response.ok || !response.body) throw new Error(`本地模型请求失败 (${response.status})`); let reply = ''; const decoder = new TextDecoder(); let buffer = ''; const emit = (raw: string) => { for (const line of raw.split(/\r?\n/)) { const value = line.trim().replace(/^data:\s*/, ''); if (!value || value === '[DONE]') continue; try { const body = JSON.parse(value) as { choices?: Array<{ delta?: { content?: string }; message?: { content?: string } }> }; const content = body.choices?.[0]?.delta?.content ?? body.choices?.[0]?.message?.content ?? ''; if (content) { reply += content; send({ type: 'model.text.delta', payload: { runtime: 'local', run_id: runId, content } }) } } catch {} } }; for await (const chunk of response.body as unknown as AsyncIterable<Uint8Array>) { buffer += decoder.decode(chunk, { stream: true }); const parts = buffer.split(/\r?\n\r?\n/); buffer = parts.pop() ?? ''; parts.forEach(emit) } if (buffer.trim()) emit(buffer); if (!reply) throw new Error('本地模型没有返回文本'); send({ type: 'run.completed', payload: { runtime: 'local', run_id: runId, conversation_id: conversationId, agent_id: request.agentId, model_key: config.id, reply } }); return { reply, conversationId, agentId: request.agentId, modelKey: config.id, runId } }
function handleTrusted(channel: string, handler: (event: Electron.IpcMainInvokeEvent, ...args: any[]) => unknown): void { ipcMain.handle(channel, (event, ...args) => { assertTrustedSender(event); return handler(event, ...args) }) }
function createRunId(): string { return `${Date.now()}-${Math.random().toString(36).slice(2, 8)}` }
function runCommand(command: string, args: string[], cwd: string, sessionId: string, send: (event: RunEvent) => void): Promise<number> { return new Promise((resolveRun, rejectRun) => { let outputLength = 0; const child = spawn(command, args, { cwd, shell: false, windowsHide: true, env: minimalChildEnv() }); activeRuns.set(sessionId, child); const handoffSession = handoffSessions.get(sessionId); if (handoffSession) handoffSession.child = child; const timeout = setTimeout(() => { send({ sessionId, stream: 'system', content: `执行超过 ${RUN_TIMEOUT_MS / 1000} 秒，已停止。\n` }); child.kill() }, RUN_TIMEOUT_MS); const emit = (stream: 'stdout' | 'stderr', chunk: Buffer) => { if (outputLength >= MAX_OUTPUT_LENGTH) return; const content = chunk.toString().slice(0, MAX_OUTPUT_LENGTH - outputLength); outputLength += content.length; send({ sessionId, stream, content }) }; child.stdout.on('data', (chunk: Buffer) => emit('stdout', chunk)); child.stderr.on('data', (chunk: Buffer) => emit('stderr', chunk)); child.once('error', (error) => { clearTimeout(timeout); activeRuns.delete(sessionId); if (handoffSession?.child === child) handoffSession.child = undefined; rejectRun(error) }); child.once('close', (code) => { clearTimeout(timeout); activeRuns.delete(sessionId); if (handoffSession?.child === child) handoffSession.child = undefined; resolveRun(code ?? -1) }) }) }
async function executeFile(workspace: string, filePath: string, mode: RunMode, sessionId: string, send: (event: RunEvent) => void): Promise<void> { const sourcePath = assertWithinWorkspace(workspace, filePath); const extension = extname(sourcePath).toLowerCase(); const sourceDirectory = dirname(sourcePath); const baseName = parse(sourcePath).name; const buildDirectory = join(workspace, '.idea-assistant', 'build'); const buildOutput = join(buildDirectory, `${baseName}.exe`); await mkdir(buildDirectory, { recursive: true }); const run = (command: string, args: string[], cwd = sourceDirectory) => runCommand(command, args, cwd, sessionId, send); const compileAndRun = async (command: string, compileArgs: string[], runner: string, runnerArgs: string[]) => { send({ sessionId, stream: 'system', content: `$ ${command} ${compileArgs.join(' ')}\n` }); if (await run(command, compileArgs) !== 0) throw new Error('编译失败'); send({ sessionId, stream: 'system', content: `$ ${runner} ${runnerArgs.join(' ')}\n` }); if (await run(runner, runnerArgs) !== 0) throw new Error('运行失败') }; if (mode === 'debug' && !['.js', '.mjs', '.cjs'].includes(extension)) throw new Error('当前语言的断点调试需要独立 Debug Adapter，第一版仅支持 Node.js Inspector 调试。'); if (['.js', '.mjs', '.cjs'].includes(extension)) { const args = mode === 'debug' ? ['--inspect-brk=127.0.0.1:0', sourcePath] : [sourcePath]; if (await run('node', args) !== 0) throw new Error('Node.js 结束异常'); return } if (extension === '.py') { if (await run('python', [sourcePath]) !== 0) throw new Error('Python 结束异常'); return } if (extension === '.go') { if (await run('go', ['run', sourcePath]) !== 0) throw new Error('Go 结束异常'); return } if (extension === '.ts') return compileAndRun('tsc', [sourcePath, '--outDir', buildDirectory, '--target', 'ES2022', '--module', 'commonjs', '--skipLibCheck'], 'node', [join(buildDirectory, `${baseName}.js`)]); if (['.c', '.cc', '.cpp', '.cxx'].includes(extension)) return compileAndRun('g++', [sourcePath, '-o', buildOutput], buildOutput, []); if (extension === '.rs') return compileAndRun('rustc', [sourcePath, '-o', buildOutput], buildOutput, []); if (extension === '.java') return compileAndRun('javac', ['-d', buildDirectory, sourcePath], 'java', ['-cp', buildDirectory, baseName]); throw new Error('当前文件类型不支持运行') }
async function buildFileTree(directory: string, depth = 0): Promise<FileEntry[]> { if (depth > 4) return []; const entries = await readdir(directory, { withFileTypes: true }); return Promise.all(entries.filter((entry) => !entry.name.startsWith('.') && !(entry.isDirectory() && SKIPPED_DIRECTORIES.has(entry.name))).sort((left, right) => Number(right.isDirectory()) - Number(left.isDirectory()) || left.name.localeCompare(right.name)).slice(0, 250).map(async (entry) => { const fullPath = join(directory, entry.name); return entry.isDirectory() ? { name: entry.name, path: fullPath, kind: 'directory' as const, children: await buildFileTree(fullPath, depth + 1) } : { name: entry.name, path: fullPath, kind: 'file' as const } })) }
async function createWindow(): Promise<void> { const window = new BrowserWindow({ width: 1480, height: 920, minWidth: 1120, minHeight: 700, backgroundColor: '#0c111c', titleBarStyle: 'hidden', titleBarOverlay: { color: '#141521', symbolColor: '#d7dde8', height: 34 }, autoHideMenuBar: true, webPreferences: { preload: join(currentDir, 'preload.cjs'), contextIsolation: true, nodeIntegration: false, sandbox: true, additionalArguments: isOwnerClient ? ['--idea-owner-client'] : [] } }); window.webContents.setWindowOpenHandler(({ url }) => { if (url.startsWith('https://')) void shell.openExternal(url); return { action: 'deny' } }); window.webContents.on('will-navigate', (event, url) => { const allowed = isDevelopment ? url.startsWith('http://127.0.0.1:5173') : url.startsWith('file://'); if (!allowed) event.preventDefault() }); if (isDevelopment) await window.loadURL('http://127.0.0.1:5173'); else await window.loadFile(join(currentDir, '..', 'dist', 'index.html')) }
let serviceTestWindow: BrowserWindow | undefined
async function createServiceTestWindow(): Promise<void> { if (serviceTestWindow && !serviceTestWindow.isDestroyed()) { serviceTestWindow.focus(); return } serviceTestWindow = new BrowserWindow({ width: 980, height: 760, minWidth: 720, minHeight: 560, backgroundColor: '#0c111c', titleBarStyle: 'hidden', titleBarOverlay: { color: '#141521', symbolColor: '#d7dde8', height: 34 }, autoHideMenuBar: true, webPreferences: { preload: join(currentDir, 'preload.cjs'), contextIsolation: true, nodeIntegration: false, sandbox: true, additionalArguments: isOwnerClient ? ['--idea-owner-client'] : [] } }); serviceTestWindow.on('closed', () => { serviceTestWindow = undefined }); if (isDevelopment) await serviceTestWindow.loadURL('http://127.0.0.1:5173?surface=service-test'); else await serviceTestWindow.loadFile(join(currentDir, '..', 'dist', 'index.html'), { query: { surface: 'service-test' } }) }

ipcMain.handle('window:service-test', (event) => { assertTrustedSender(event); return createServiceTestWindow() })
ipcMain.handle('local:agent-status', async (event) => { assertTrustedSender(event); const config = await loadLocalModelConfig(); return { status: config.configured ? 'ready' as const : 'unconfigured' as const, runtime: 'local' as const, capabilities: ['workspace.context', 'file.read', 'local.reply'], model: publicLocalModelConfig(config) } })
ipcMain.handle('local:model-config', async (event) => { assertTrustedSender(event); return publicLocalModelConfig(await loadLocalModelConfig()) })
ipcMain.handle('local:models', async (event) => { assertTrustedSender(event); return readOfficialModels() })
ipcMain.handle('local:extensions', async (event) => { assertTrustedSender(event); try { return JSON.parse(await readFile(localExtensionsPath(), 'utf8')) } catch { return { mcp: [], rules: [] } } })
ipcMain.handle('local:save-extensions', async (event, input: { mcp: Array<{ name: string; url: string; enabled: boolean }>; rules: Array<{ name: string; content: string; enabled: boolean }> }) => { assertTrustedSender(event); await mkdir(dirname(localExtensionsPath()), { recursive: true }); await writeFile(localExtensionsPath(), JSON.stringify(input), 'utf8'); return input })
ipcMain.handle('local:save-model-config', async (event, input: { id?: string; name?: string; displayName?: string; provider?: string; baseUrl: string; model: string; apiKey: string }) => { assertTrustedSender(event); return saveLocalModelConfig(input) })
ipcMain.handle('local:chat-stream', (event, request: { agentId: string; message: string; contextBlocks?: Array<{ path: string; name: string; content: string }>; conversationId?: string; useMemory?: boolean; modelKey?: ModelKey }) => { assertTrustedSender(event); return localChatStream(request, (streamEvent) => event.sender.send('local:chat-event', streamEvent)) })
